// ===== BP — Sales DB Hygiene : Classify & Plan =====
// Runs once for all items. Input: every page of BP — Companies Sales DB.
// Output: only the records that need a write, tagged with _action + _reason.

// Domains proven undeliverable by a live DNS check (NXDOMAIN or no mail exchanger).
const DEAD_DOMAINS = new Set(["7brand-sa.com","abhais.edu.sa","acic-ksa.com","al-omaier.com","alassimi-law.com","albassamschools.edu.sa","alemaaralareq.com","alexiahotels.com","alhadafelamny.com","alhamads.com","alharbiholding.com","alkifahprecast.com","almosanadah.net","alnagah-clean.com","aom-company.com","app.beyah.sa","aybmedical.company","bbd.sa","be.besmartksa.com","bml.med.sa","bn-shmashyer.com","cgshool.com.sa","citytechsa.com","company.sa","doroob-roze.com","eamaraseer.sa","eisa4044.sa","elsakrplastic.com","etspices.com","farajalofi.com","firstgulfcompany.com","flglc.com","flyto-sky.com","friend2020.com","goharamarket.com","goldenl.sa","greenarrowac.com","h-sakan.com","health-dimension.com","hospital.kau.edu.sa","jewaralsafwahsa.com","kaah.med.sa","kinona.sa","lanaiis.in","lcc.sa","lifelines-store.com","mah.sa","masadar.com.sa","medad-medical.com","medpromedicals.com","nano.com.sa","nequlalarabia.com","odata.type","orisderma.com","qistlaw.sa","rct.edu.sa","rehabalmadinaa.com","saad-international.com","safarplustravels.net","salama-team.com","sattahmakkhahservice.com","sawarifuture.com","sepcoarabia.com","shodeshtravel.com","shorfarealestate.com","square1sa.com","sultanrec.com","thekrsch.com","toolsworldksa.redintek.in","tzaidd.com","untitled.tld","uod.edu.sa","wajen.sa","wwww.printazone.com","69317660ca139.site123.me","6a1b9bc50bcbb.site123.me","6a221a25a1202.site123.me","ain.com","alshmukh.adalo.com","api.whatsapp.com","apps.apple.com","aqspepsi.wordpress.com","buruj.sa","cdn.qr-code-generator.com","cholarestaurant.coreninesolutions.com","en.zoomlion.com","jasminegardenhotel.seebooking.com","kfsh.med.sa","m.facebook.com","me.marsh.com","qr.finedinemenu.com","sa.hm.com","srexpress.com","training.alkhaleej.com.sa","-ascott.com"]);

// Real inboxes, but they belong to a global platform — never to the prospect.
const PLATFORM_DOMAINS = new Set(["booking.com","expedia.com","google.com","goo.gl","maps.app.goo.gl","instagram.com","facebook.com","tiktok.com","x.com","twitter.com","linkedin.com","snapchat.com","framer.com","flowcode.com","myqrcode.com","instabio.cc","n9.cl","qrco.de","salla.sa","vip.com","adobe.com","sentry.io","wixpress.com","yaschools.com","bayut.sa","jomla.me","stagheaddesigns.com","indiantypefoundry.com","micahrich.com","reserval.com","mysecurecloudhost.com","hyattrestaurants.com","marriott.com","radissonhotels.com","millenniumhotels.com","swissotel.com","warwickhotels.com","wyndham.com","otis.com"]);

// Site-builder / booking-engine / link-tool suffixes — the address is the vendor's, not the company's.
const PLATFORM_SUFFIXES = [".site123.me",".lovable.app",".adalo.com",".weebly.com",".wordpress.com",".foodics.online",".classera.com",".bookmystay.io",".seebooking.com",".joodbooking.com",".verticalbooking.com",".hotelmold.top",".baab.com",".zaaer.co",".finedinemenu.com",".redintek.in",".wiandk.app",".coreninesolutions.com",".pics.ee",".qr-code-generator.com"];

// Sample/demo addresses left behind in a website template.
const PLACEHOLDER_DOMAINS = new Set(["company.com","mysite.com","domain.com","email.com","example.com","example.org","yourwebsite.com","yourdomain.com","yoursite.com","compant.com","blocks.com","hq.com","realesatate.com","untitled.tld","domain.tld","test.com","site.com","mail.com"]);
const PLACEHOLDER_LOCALS = new Set(["example","your","yourname","youremail","yourmail","email","test","name","firstname","username","sample","demo"]);

const RE_EMAIL = /^[a-z0-9._%+'-]+@[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+$/;

function normalise(raw) {
  if (!raw) return "";
  let s = String(raw).trim();
  // Scraped values arrive URL-encoded and sometimes carry several addresses.
  try { s = decodeURIComponent(s); } catch (e) { s = s.replace(/%20/g, " "); }
  s = s.replace(/^mailto:/i, "");
  const parts = s.split(/[,;\s<>()\[\]]+/).map(p => p.trim().toLowerCase()).filter(Boolean);
  for (const p of parts) if (RE_EMAIL.test(p)) return p;
  return "";
}

function isPlatform(d) {
  if (PLATFORM_DOMAINS.has(d)) return true;
  return PLATFORM_SUFFIXES.some(sfx => d.endsWith(sfx));
}

const rows = [];
for (const item of $input.all()) {
  const j = item.json;
  rows.push({
    pageId: j.id,
    raw: j.property_email || j.email || "",
    sent: j.property_campaign_sent === true,
    suppressed: j.property_suppressed === true,
    score: Number(j.property_icp_score) || 0,
    name: (j.property_name || j.name || "").toString(),
  });
}

const plan = [];
const stats = { total: rows.length, no_email: 0, ok: 0, fixed: 0, invalid: 0, dead: 0, platform: 0, placeholder: 0, duplicate: 0, already: 0 };

// Pass 1 — normalise, then judge each address on its own merits.
for (const r of rows) {
  if (r.suppressed) { stats.already++; r.skip = true; continue; }
  if (!String(r.raw).trim()) { stats.no_email++; r.skip = true; continue; }

  const email = normalise(r.raw);
  r.email = email;

  if (!email) { r.verdict = "Invalid Syntax"; stats.invalid++; continue; }

  const domain = email.split("@")[1];
  const local = email.split("@")[0];

  if (DEAD_DOMAINS.has(domain)) { r.verdict = "Undeliverable Domain"; stats.dead++; continue; }
  if (isPlatform(domain)) { r.verdict = "Global Platform"; stats.platform++; continue; }
  if (PLACEHOLDER_DOMAINS.has(domain) || PLACEHOLDER_LOCALS.has(local)) { r.verdict = "Placeholder"; stats.placeholder++; continue; }

  r.verdict = "";
  if (email !== String(r.raw).trim().toLowerCase()) stats.fixed++; else stats.ok++;
}

// Pass 2 — one address, one record. Keep the copy that already received mail,
// otherwise the highest-scoring one, and suppress the rest.
const groups = new Map();
for (const r of rows) {
  if (r.skip || r.verdict || !r.email) continue;
  if (!groups.has(r.email)) groups.set(r.email, []);
  groups.get(r.email).push(r);
}
for (const [, group] of groups) {
  if (group.length < 2) continue;
  group.sort((a, b) => (b.sent - a.sent) || (b.score - a.score));
  for (const dup of group.slice(1)) { dup.verdict = "Duplicate"; stats.duplicate++; }
}

// Pass 3 — emit only the records that need a write.
for (const r of rows) {
  if (r.skip) continue;
  const changed = r.email && r.email !== String(r.raw).trim();
  if (r.verdict) {
    plan.push({ json: {
      _pageId: r.pageId, _action: "suppress", _reason: r.verdict,
      _email: r.email || "", _origEmail: String(r.raw).trim(), _company: r.name,
      _wasSent: r.sent, _summary: stats,
    }});
  } else if (changed) {
    plan.push({ json: {
      _pageId: r.pageId, _action: "fix", _reason: "Email normalised",
      _email: r.email, _origEmail: String(r.raw).trim(), _company: r.name,
      _wasSent: r.sent, _summary: stats,
    }});
  }
}

console.log("HYGIENE SUMMARY", JSON.stringify(stats));
console.log("records to write:", plan.length);
return plan;
